-- Comprobación
select
  count(*) as ejemplares,
  count(*) filter (where padre_id is not null) as con_padre,
  count(*) filter (where sexo is not null) as con_sexo,
  count(*) filter (where propietario_id is not null) as con_propietario
from perros;
